CREATE TABLE IF NOT EXISTS asset_evidence_nodes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), node_type text NOT NULL, entity_reference text NOT NULL, canonical_label text NOT NULL, jurisdiction_code text, source_reference text, authority_level text NOT NULL DEFAULT 'Unknown', verification_status text NOT NULL DEFAULT 'Unverified', confidence_score numeric(5,2), first_seen_at timestamptz NOT NULL DEFAULT now(), last_verified_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS asset_evidence_edges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_node_id uuid REFERENCES asset_evidence_nodes(id) ON DELETE CASCADE, to_node_id uuid REFERENCES asset_evidence_nodes(id) ON DELETE CASCADE, relation_type text NOT NULL, assertion text, source_reference text, verification_status text NOT NULL DEFAULT 'Unverified', confidence_score numeric(5,2), effective_from date, effective_to date, reviewer_reference text, created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS asset_evidence_assertions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, onboarding_case_id uuid REFERENCES asset_onboarding_cases(id) ON DELETE SET NULL, subject_node_id uuid REFERENCES asset_evidence_nodes(id) ON DELETE CASCADE, predicate text NOT NULL, object_node_id uuid REFERENCES asset_evidence_nodes(id) ON DELETE SET NULL, literal_value text, source_reference text, evidence_reference text, verification_status text NOT NULL DEFAULT 'Unverified', confidence_score numeric(5,2), assertion_status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_evidence_conflicts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, conflict_type text NOT NULL, severity text NOT NULL DEFAULT 'Medium', description text NOT NULL, assertion_a_id uuid REFERENCES asset_evidence_assertions(id) ON DELETE SET NULL, assertion_b_id uuid REFERENCES asset_evidence_assertions(id) ON DELETE SET NULL, detected_at timestamptz NOT NULL DEFAULT now(), resolution_status text NOT NULL DEFAULT 'Open', resolution_reference text, resolved_by text, resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS asset_evidence_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, node_id uuid REFERENCES asset_evidence_nodes(id) ON DELETE SET NULL, edge_id uuid REFERENCES asset_evidence_edges(id) ON DELETE SET NULL, assertion_id uuid REFERENCES asset_evidence_assertions(id) ON DELETE SET NULL, event_type text NOT NULL, actor_reference text, source_reference text, event_hash text, previous_event_hash text, event_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS idx_evidence_nodes_entity ON asset_evidence_nodes(node_type,entity_reference);
CREATE INDEX IF NOT EXISTS idx_evidence_edges_relation ON asset_evidence_edges(relation_type,verification_status);
CREATE INDEX IF NOT EXISTS idx_evidence_assertions_asset ON asset_evidence_assertions(asset_id,assertion_status);
CREATE INDEX IF NOT EXISTS idx_evidence_conflicts_asset ON asset_evidence_conflicts(asset_id,resolution_status);